        "key_scenes": ["清晨醒来", "倒计时出现", "内心崩塌"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "十二小时",
        "core_event": "沈砚北决定在不暴露的情况下开始调查：她为什么要杀我？",
