        "key_scenes": ["真相对白", "她的崩溃", "爱的证据"]
      },
      {
        "chapter_number": 45,
        "chapter_title": "选择",
        "core_event": "他说：如果救陈礼安的代价是让你成为凶手，我选择不救",
        "emotional_tone": "撕裂/抉择",
        "key_scenes": ["他的选择", "她的动摇", "双重牺牲的开始"]
      },
      {
